var a=`1223-hojaldres`;var n=`world-1223`;var t=`PA`;var r=`central-america-caribbean`;var s=8;var o=46;var d={en:`Hojaldres`,ua:`Охальдрес`};var l={en:`Hojaldres is a dish from Panama featuring all-purpose flour, baking powder. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Охальдрес, страва кухні країни Панама з такими основними складниками: пшеничне борошно універсальне, розпушувач тіста. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,480,`g`],[`baking-powder`,17,`g`],[`table-salt`,8,`g`],[`water`,270,`ml`],[`unsalted-butter`,55,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:11,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 16 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 16 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:16,i:[[`canola-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,80,`g`]]}];var g={slug:a,id:n,country:`PA`,region:r,servings:8,minutes:46,title:d,text:l,steps:u};export{t as country,g as default,n as id,o as minutes,r as region,s as servings,a as slug,u as steps,l as text,d as title};